-- Views the engine loads (DATA-03; docs/spec/01_data_model.md section 4).
-- security_invoker: the caller's privileges and row-level security apply to the underlying tables
-- (app.tenant_id, 0002_rls.sql). Without it a view runs as its owner and would bypass RLS.
-- A view cannot take parameters: "v_inputs_resolved(tenant, scenario)" is the view filtered on
-- tenant_id and scenario_id (scenario_id NULL = the tenant defaults alone), ordered by the caller.

CREATE VIEW v_inputs_resolved WITH (security_invoker = true) AS
WITH RECURSIVE chain (tenant_id, scenario_id, ancestor_id, parent_id, depth, path) AS (
  -- every scenario with its ancestors: depth 0 is the scenario itself, then its parent, and so on to the root
  SELECT s.tenant_id, s.id, s.id, s.parent_id, 0, ARRAY[s.id]
  FROM scenario s
  UNION ALL
  SELECT c.tenant_id, c.scenario_id, p.id, p.parent_id, c.depth + 1, c.path || p.id
  FROM chain c
  JOIN scenario p ON p.id = c.parent_id AND p.tenant_id = c.tenant_id
  WHERE p.id <> ALL (c.path) -- a parent cycle ends the chain instead of looping
),
targets AS (
  SELECT s.tenant_id, s.id AS scenario_id FROM scenario s
  UNION ALL
  SELECT t.id, NULL::uuid FROM tenant t -- scenario_id NULL: the tenant defaults alone
),
candidates AS (
  -- tenant default (depth NULL: the lowest level)
  SELECT g.tenant_id, g.scenario_id, v.var_key, v.member_key, v.value,
         NULL::integer AS depth, NULL::uuid AS from_scenario_id, v.confidence, v.note
  FROM targets g
  JOIN variable_value v ON v.tenant_id = g.tenant_id
  UNION ALL
  -- the scenario's own values (depth 0) and its ancestors' (depth 1 = parent, up to the root)
  SELECT c.tenant_id, c.scenario_id, sv.var_key, sv.member_key, sv.value,
         c.depth, c.ancestor_id, NULL::bpchar, NULL::text
  FROM chain c
  JOIN scenario_value sv ON sv.tenant_id = c.tenant_id AND sv.scenario_id = c.ancestor_id
),
resolved AS (
  -- last level wins per (scenario, var_key, member_key): nearest ancestor first, tenant default last.
  -- Only variables of the model version the tenant pins (stale rows of an older model are dropped).
  SELECT DISTINCT ON (c.tenant_id, c.scenario_id, c.var_key, c.member_key)
         c.tenant_id, c.scenario_id, c.var_key, c.member_key, c.value, c.depth, c.from_scenario_id, c.confidence, c.note
  FROM candidates c
  JOIN tenant t ON t.id = c.tenant_id
  JOIN variable_def d ON d.model_version_id = t.model_version_id AND d.var_key = c.var_key
  ORDER BY c.tenant_id, c.scenario_id, c.var_key, c.member_key, c.depth NULLS LAST
)
SELECT r.tenant_id,
       r.scenario_id,
       'input'::text AS kind,
       r.var_key AS key,
       r.member_key,
       r.value,
       CASE WHEN r.depth IS NULL THEN 'tenant' WHEN r.depth = 0 THEN 'scenario' ELSE 'parent' END::text AS resolved_from,
       r.from_scenario_id,
       r.confidence,
       r.note,
       NULL::text AS reason
FROM resolved r
UNION ALL
-- the scenario's own node overrides: not inherited from ancestors
SELECT o.tenant_id,
       o.scenario_id,
       'override'::text,
       o.node_key,
       o.member_key,
       o.value,
       'scenario'::text,
       o.scenario_id,
       NULL::bpchar,
       NULL::text,
       o.reason
FROM node_override o;

COMMENT ON VIEW v_inputs_resolved IS 'For (tenant, scenario): variable_def LEFT JOIN variable_value LEFT JOIN scenario_value chain (scenario -> parent -> tenant default). What the engine loads. Columns: tenant_id, scenario_id (NULL = tenant defaults), kind (input | override), key (var_key or node_key), member_key, value, resolved_from (tenant | parent | scenario), from_scenario_id, confidence, note, reason. Filter on tenant_id and scenario_id.';

CREATE VIEW v_dimension_members WITH (security_invoker = true) AS
-- global members (tenant_id NULL): visible to every tenant
SELECT NULL::uuid AS tenant_id, 'pool'::text AS dim_key, p.id AS member_key, p.label,
       jsonb_build_object('third_party', p.third_party::int, 'order', p.sort) AS attrs,
       p.sort, true AS active, 'global'::text AS origin
FROM canonical_pool p
UNION ALL
SELECT NULL::uuid, 'addr_tag', a.id, a.label, '{}'::jsonb,
       (row_number() OVER (ORDER BY a.id COLLATE "C"))::integer, true, 'global'
FROM addr_tag a
UNION ALL
-- system dimensions: members of the model, no table holds them (spec bundle)
SELECT NULL::uuid, s.dim_key, s.member_key, s.label, s.attrs, s.sort, true, 'system'
FROM (VALUES
    ('akey', 'internal_labour', 'US labour', '{}'::jsonb, 1),
    ('akey', 'captive_labour', 'India GCC', '{}'::jsonb, 2),
    ('akey', 'si_contingent', 'SI & contingent', '{}'::jsonb, 3),
    ('akey', 'consulting', 'Consulting', '{}'::jsonb, 4),
    ('akey', 'software', 'Software', '{}'::jsonb, 5),
    ('akey', 'airline_platforms', 'Airline platforms', '{}'::jsonb, 6),
    ('akey', 'cloud', 'Cloud', '{}'::jsonb, 7),
    ('akey', 'dc_hardware', 'DC & hardware', '{}'::jsonb, 8),
    ('akey', 'network', 'Network', '{}'::jsonb, 9),
    ('akey', 'end_user', 'End-user', '{}'::jsonb, 10),
    ('akey', 'other', 'Other', '{}'::jsonb, 11),
    ('akey', 'apps', 'Apps (SI split proxy)', '{}'::jsonb, 12),
    ('akey', 'blend', 'Third-party blend', '{}'::jsonb, 13),
    ('year', 'fy25', 'FY2025A', '{"in":"fy25","prev":"","it":0}'::jsonb, 1),
    ('year', 'fy26', 'FY2026E', '{"in":"fy26","prev":"fy25","it":0}'::jsonb, 2),
    ('year', 'fy27b', 'FY2027E base', '{"in":"fy27","prev":"fy26","it":0}'::jsonb, 3),
    ('year', 'fy27it', 'FY2027E + IT', '{"in":"fy27","prev":"fy26","it":1}'::jsonb, 4),
    ('iyear', 'fy25', 'FY2025A', '{}'::jsonb, 1),
    ('iyear', 'fy26', 'FY2026E', '{}'::jsonb, 2),
    ('iyear', 'fy27', 'FY2027E', '{}'::jsonb, 3)
) AS s (dim_key, member_key, label, attrs, sort)
UNION ALL
-- tenant members (vp, domain, vendor, lgroup, lever, ...); never the dimensions served above
SELECT m.tenant_id, m.dim_key, m.member_key, m.label, m.attrs, m.sort, m.active, 'tenant'
FROM dimension_member m
WHERE m.dim_key NOT IN ('pool', 'addr_tag', 'akey', 'year', 'iyear')
UNION ALL
-- baseline lines: their own table, attributes under the names expressions use (line.pool, line.domain, ...)
SELECT li.tenant_id, 'line', li.member_key, li.name,
       jsonb_build_object(
      'pool', li.pool_id,
      'domain', li.domain_key,
      'addr', li.addr_tag,
      'drv', li.scale_driver::text,
      'l2', li.l2,
      'name', li.name,
      'vendor', li.vendor_key,
      'nature', li.nature,
      'accounting', li.accounting,
      'lever_ids', lv.lever_ids,
      'in_scope', li.in_scope::int,
      'memo', li.memo::int,
      'confidence', li.confidence::text,
      'source', src.code,
      'legacy_id', li.legacy_id
       ),
       (row_number() OVER (PARTITION BY li.tenant_id ORDER BY li.member_key COLLATE "C"))::integer,
       li.active, 'line_item'
FROM line_item li
LEFT JOIN source src ON src.id = li.source_id
LEFT JOIN LATERAL (
  SELECT COALESCE(jsonb_agg(l.lever_code ORDER BY l.lever_code COLLATE "C"), '[]'::jsonb) AS lever_ids
  FROM line_item_lever l
  WHERE l.tenant_id = li.tenant_id AND l.line_key = li.member_key
) lv ON true;

COMMENT ON VIEW v_dimension_members IS 'UNION of global members (canonical_pool, addr_tag, system dims), dimension_member, and line_item, with attrs as jsonb. Columns: tenant_id (NULL = global), dim_key, member_key, label, attrs, sort, active, origin (global | system | tenant | line_item).';

GRANT SELECT ON v_inputs_resolved, v_dimension_members TO glidepath_app;
